#include <stdio.h>
#include <string.h>

int is_vowel(char c) {
    return c != '\0' && strchr("aeiou", c) != NULL;
}

int main() {
    char s[] = "programming language";
    int count = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (is_vowel(s[i])) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}
